            Status,
        });

        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        await expect(promise).rejects.toEqual({ tryAgain: true });
    });

    it('should re-try to confirm until the tab is closed', async () => {
        api.mockResolvedValue({
            Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE,
        });

        const delayListening = 10;
        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token }, delayListening);
        await delay(delayListening * 5);

        tab.closed = true;

        await expect(promise).resolves.toEqual(undefined);
    });
});

import { useEffect, useRef } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { createToken, setPaymentMethod } from '@proton/shared/lib/api/payments';
import { BRAND_NAME, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';

import { ModalProps, Prompt } from '../../components';
import { useApi, useEventManager, useLoading, useNotifications } from '../../hooks';
import { PaymentTokenResult } from './interface';
import { process } from './paymentTokenHelper';

const PAYMENT_AUTHORIZATION_AMOUNT = 100;
const PAYMENT_AUTHORIZATION_CURRENCY = 'CHF';

const PayPalModal = ({ onClose, ...rest }: ModalProps) => {
    const api = useApi();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loadingToken, withLoadingToken] = useLoading();
    const [loading, withLoading] = useLoading();
    const abortRef = useRef<AbortController>();
    const paypalRef = useRef<PaymentTokenResult | undefined>();
    const paymentMethodType = PAYMENT_METHOD_TYPES.PAYPAL;

    useEffect(() => {
        const run = async () => {
            const result = await api<PaymentTokenResult>(
                createToken({
                    Amount: PAYMENT_AUTHORIZATION_AMOUNT,
                    Currency: PAYMENT_AUTHORIZATION_CURRENCY,
                    Payment: {
                        Type: paymentMethodType,
                    },
                })
            );
            paypalRef.current = result;
        };
        void withLoadingToken(run());
        return () => {
            abortRef.current?.abort();
        };
    }, []);

    const handleSubmit = async (data: PaymentTokenResult) => {
        abortRef.current = new AbortController();
        await process({
            Token: data.Token,
            api,
            ApprovalURL: data.ApprovalURL,
            ReturnHost: data.ReturnHost,
            signal: abortRef.current.signal,
        });
        await api(
            setPaymentMethod({
                Type: PAYMENT_METHOD_TYPES.TOKEN,
                Details: {
                    Token: data.Token,
                },
            })
        );
        await call();
        onClose?.();
        createNotification({ text: c('Success').t`Payment method added` });
    };

    return (
        <Prompt
            data-testid="addPPalModalTitle"
            title={c('Title').t`Add PayPal payment method`}
            onClose={onClose}
            buttons={[
                <Button
                    color="norm"
                    loading={loading}
                    disabled={loadingToken}
                    onClick={() => {
                        if (!paypalRef.current) {
                            return;
                        }
                        void withLoading(handleSubmit(paypalRef.current));
                    }}
                >{c('Action').t`Add PayPal`}</Button>,
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            {loading ? (
                <>
                    <div className="mb-4">{c('Info').t`Please verify payment at the new tab which was opened.`}</div>
                    <div>{c('Info').t`Verification can take a few minutes.`}</div>
                </>
            ) : (
                <>
                    <div className="mb-4">
                        {c('Info')
                            .t`This will enable PayPal to be used to pay for your ${BRAND_NAME} subscription. We will redirect you to PayPal in a new browser tab. If you use any pop-up blockers, please disable them to continue.`}
                    </div>
                    <div>
                        {c('Info')
                            .t`You must have a credit card or bank account linked with your PayPal account in order to add it as a payment method.`}
                    </div>
                </>
            )}
        </Prompt>
    );
};

export default PayPalModal;

import { useState } from 'react';

import { createToken } from '@proton/shared/lib/api/payments';
import { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';
import { Currency } from '@proton/shared/lib/interfaces';

import { useApi, useLoading, useModals } from '../../hooks';
import PaymentVerificationModal from './PaymentVerificationModal';
import { AmountAndCurrency, TokenPaymentMethod } from './interface';
import { process } from './paymentTokenHelper';

interface Model {
    Token: string;
    ApprovalURL: string;
    ReturnHost: string;
}

const DEFAULT_MODEL = {
    Token: '',
    ApprovalURL: '',
    ReturnHost: '',
};

export interface PayPalHook {
    isReady: boolean;
    loadingToken: boolean;
    loadingVerification: boolean;
    onToken: () => Promise<void>;
    onVerification: () => Promise<void>;
    clear: () => void;
}

type PAYPAL_PAYMENT_METHOD = PAYMENT_METHOD_TYPES.PAYPAL | PAYMENT_METHOD_TYPES.PAYPAL_CREDIT;

export type OnPayResult = TokenPaymentMethod & AmountAndCurrency & { type: PAYPAL_PAYMENT_METHOD };

interface Props {
    amount: number;
    currency: Currency;
    type: PAYPAL_PAYMENT_METHOD;
    onPay: (data: OnPayResult) => void;
    onValidate?: () => Promise<boolean>;
}

const usePayPal = ({ amount = 0, currency: Currency, type: Type, onPay, onValidate }: Props) => {
    const api = useApi();
    const [model, setModel] = useState<Model>(DEFAULT_MODEL);
    const [loadingVerification, withLoadingVerification] = useLoading();
    const [loadingToken, withLoadingToken] = useLoading();
    const { createModal } = useModals();
    const clear = () => setModel(DEFAULT_MODEL);

    const onToken = async () => {
        try {
            const result = await api<{ Token: string; ApprovalURL: string; ReturnHost: string }>(
                createToken({
                    Amount: amount,
                    Currency,
                    Payment: { Type },
                })
            );
            setModel(result);
        } catch (error: any) {
            clear();
            throw error;
        }
    };

    const onVerification = async () => {
        const { Token, ApprovalURL, ReturnHost } = model;
        const tokenPaymentMethod = await new Promise<TokenPaymentMethod>((resolve, reject) => {
            const onProcess = () => {
                const abort = new AbortController();
                return {
                    promise: process({
                        Token,
                        api,
                        ReturnHost,
                        ApprovalURL,
                        signal: abort.signal,
                    }),
                    abort,
                };
            };
            createModal(
                <PaymentVerificationModal
                    token={Token}
                    onSubmit={resolve}
                    onClose={reject}
                    type={Type}
                    onProcess={onProcess}
                    initialProcess={onProcess()}
                />
            );
        });

        onPay({ ...tokenPaymentMethod, Amount: amount, Currency, type: Type });
    };

    return {
        isReady: !!model.Token,
        loadingToken,
        loadingVerification,
        onToken: async () => {
            return withLoadingToken(onToken());
        },
        onVerification: async () => {
            if (!((await onValidate?.()) ?? true)) {
                return;
            }
            return withLoadingVerification(onVerification());
        },
        clear,
    };
};

export default usePayPal;

import { PAYMENT_METHOD_TYPES, PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { Currency } from '@proton/shared/lib/interfaces';

export interface CardPayment {
    Type: PAYMENT_METHOD_TYPES.CARD;
    Details: {
        Name: string;
        Number: string;
        ExpMonth: string;
        ExpYear: string;
        CVC: string;
        ZIP: string;
        Country: string;
    };
}

export function isCardPayment(payment: any): payment is CardPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.CARD && !!payment?.Details;
}

export interface TokenPayment {
    Type: PAYMENT_METHOD_TYPES.TOKEN;
    Details: {
        Token: string;
    };
}

export function isTokenPayment(payment: any): payment is TokenPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.TOKEN || !!(payment as any)?.Details?.Token;
}

export interface PaypalPayment {
    Type: PAYMENT_METHOD_TYPES.PAYPAL | PAYMENT_METHOD_TYPES.PAYPAL_CREDIT;
}

export interface WrappedPaypalPayment {
    Payment: PaypalPayment;
}

export function isPaypalPayment(payment: any): payment is PaypalPayment {
    return (
        payment && (payment.Type === PAYMENT_METHOD_TYPES.PAYPAL || payment.Type === PAYMENT_METHOD_TYPES.PAYPAL_CREDIT)
    );
}

export interface ExistingPayment {
    PaymentMethodID: string;
}

export function isExistingPayment(data: any): data is ExistingPayment {
    return !!data && typeof data.PaymentMethodID === 'string';
}

export interface WrappedCardPayment {
    Payment: CardPayment;
}

export interface TokenPaymentMethod {
    Payment: TokenPayment;
}

export function isTokenPaymentMethod(data: any): data is TokenPaymentMethod {
    return !!data && isTokenPayment(data.Payment);
}

export interface AmountAndCurrency {
    Amount: number;
    Currency: Currency;
}

export interface CardModel {
    fullname: string;
    number: string;
    month: string;
    year: string;
    cvc: string;
    zip: string;
    country: string;
}

export interface PaymentTokenResult {
    Token: string;
    Status: PAYMENT_TOKEN_STATUS;
    ApprovalURL?: string;
    ReturnHost?: string;
}

