import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { getHostname } from '@proton/shared/lib/helpers/url';
import { Api } from '@proton/shared/lib/interfaces';

import PaymentVerificationModal from './PaymentVerificationModal';
import {
    AmountAndCurrency,
    CardPayment,
    ExistingPayment,
    PaymentTokenResult,
    TokenPaymentMethod,
    WrappedCardPayment,
    isExistingPayment,
    isTokenPaymentMethod,
} from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } =
    PAYMENT_TOKEN_STATUS;

const DELAY_PULLING = 5000;
const MAX_POLLING_TIME = DELAY_PULLING * 30;

const getTokenStatusError = (status: PAYMENT_TOKEN_STATUS) => {
    switch (status) {
        case STATUS_FAILED:
            return new Error(c('Error').t`Payment process failed`);
        case STATUS_CONSUMED:
            return new Error(c('Error').t`Payment process consumed`);
        case STATUS_NOT_SUPPORTED:
            return new Error(c('Error').t`Payment process not supported`);
        default:
            return new Error(c('Error').t`Unknown payment token status`);
    }
};

/**
 * Open the approval tab and poll until verification finishes or the user leaves it.
 * The returned status lets callers distinguish a chargeable token from a cancelled or failed verification.
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    pollingInterval = DELAY_PULLING
): Promise<PAYMENT_TOKEN_STATUS | undefined> => {
    if (signal.aborted) {
        return Promise.resolve(undefined);
    }

    const tab = window.open(ApprovalURL);

    return new Promise<PAYMENT_TOKEN_STATUS | undefined>((resolve, reject) => {
        let timer: number | undefined;
        let elapsed = 0;
        let settled = false;
        let checking = false;
        const interval = Math.max(1, pollingInterval);

        function cleanup() {
            window.clearTimeout(timer);
            window.removeEventListener('message', onMessage, false);
            signal.removeEventListener('abort', onAbort);
            tab?.close();
        }

        function finish(status?: PAYMENT_TOKEN_STATUS, error?: unknown) {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            if (error) {
                reject(error);
            } else {
                resolve(status);
            }
        }

        function schedule() {
